    /// Returns an error if the request fails or the response cannot be decoded.
    pub fn initiate(&self, params: RegistrationInitiateParams) -> Result<RegistrationState> {
        self.client
            .block_on(self.client.as_async().registration().initiate(params))
    }

    /// Start a passwordless registration on behalf of a merchant
    ///
    /// Variant used by the embeddable merchant widget: no password, the client is linked to
    /// `merchantId` / `externalClientId`. Same headers, steps and errors as `initiate`; finish
    /// with `complete_sdk`.
    ///
    /// `POST /api/v1/registration/sdk/initiate`
    ///
    /// **Experimental:** the endpoint may change without notice.
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
    pub fn initiate_sdk(&self, params: RegistrationInitiateSdkParams) -> Result<RegistrationState> {
        self.client
            .block_on(self.client.as_async().registration().initiate_sdk(params))
    }

    /// Confirm the registration email with the emailed code
    ///
    /// Wrong codes answer `INVALID_CODE`, `INVALID_EMAIL_CODE` or `BAD_REQUEST`. The code
    /// expires after 5 minutes in the web app.
    ///
    /// `POST /api/v1/registration/email/verify`
    ///
    /// **Experimental:** the endpoint may change without notice.
    /// Public: works without signing in.
    ///
    /// # Errors
    ///
    /// Returns an error if the request fails or the response cannot be decoded.
